$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$target = Join-Path $root 'Project\Source\PluginEditor.cpp'
$refNew = Join-Path $root 'Reference\PluginEditor_STAGE113.cpp'

$txt = [System.IO.File]::ReadAllText($target)
$txt = $txt.Replace("`r`n", "`n")

if ($txt.Contains('stage113b-proc')) {
    Write-Host 'GUI_PATCH_B=ALREADY_APPLIED'
} else {
    $anchor = "g.setColour(juce::Colour(0x96050607));`n    g.fillRect(0.0f, 0.0f, baseW, baseH);"
    $c = ([regex]::Matches($txt, [regex]::Escape($anchor))).Count
    if ($c -ne 1) { throw "PATCH_A_ANCHOR_NOT_UNIQUE found=$c - patch A may not be applied" }

    $procedural = " // stage113b-proc: procedural industrial chassis (no external asset)`n    {`n        juce::Random rnd(909u);`n        for (int i = 0; i < 26; ++i)`n        {`n            const float rx = (float)rnd.nextInt((int)baseW);`n            const float ry = (float)rnd.nextInt((int)baseH);`n            const float rr = 8.0f + (float)rnd.nextInt(30);`n            const bool edge = (rx < 60.0f || rx > baseW - 60.0f || ry < 60.0f || ry > baseH - 60.0f);`n            juce::ColourGradient rust(juce::Colour(edge ? 0x6a6a3a16 : 0x306a3a16), rx, ry,`n                                      juce::Colour(0x006a3a16), rx, ry + rr, true);`n            g.setGradientFill(rust);`n            g.fillEllipse(rx - rr, ry - rr * 0.7f, rr * 2.0f, rr * 1.4f);`n        }`n        g.setColour(juce::Colour(0x14ffffff));`n        for (int i = 0; i < 40; ++i)`n        {`n            const float x1 = (float)rnd.nextInt((int)baseW);`n            const float y1 = (float)rnd.nextInt((int)baseH);`n            const float x2 = x1 + 20.0f + (float)rnd.nextInt(60);`n            const float y2 = y1 + 4.0f - (float)rnd.nextInt(8);`n            g.drawLine(juce::Line<float>(x1, y1, x2, y2), 1.0f);`n        }`n    }`n    for (const float side : { 6.0f, baseW - 12.0f })`n    {`n        juce::Path cable;`n        cable.startNewSubPath(side + 3.0f, 0.0f);`n        cable.cubicTo(side - 4.0f, baseH * 0.3f, side + 10.0f, baseH * 0.6f, side + 3.0f, baseH);`n        g.setColour(juce::Colour(0xff0c0e10));`n        g.strokePath(cable, juce::PathStrokeType(8.0f));`n        g.setColour(juce::Colour(0x2affffff));`n        g.strokePath(cable, juce::PathStrokeType(1.6f));`n        for (const float gy : { baseH * 0.28f, baseH * 0.62f })`n        {`n            g.setColour(juce::Colour(0xff565c60));`n            g.fillRoundedRectangle(side - 4.0f, gy, 14.0f, 18.0f, 2.0f);`n            g.setColour(juce::Colour(0xff0a0c0d));`n            g.drawRoundedRectangle(side - 4.0f, gy, 14.0f, 18.0f, 2.0f, 1.0f);`n        }`n    }`n    {`n        juce::Rectangle<float> stick(baseW - 96.0f, 96.0f, 44.0f, 32.0f);`n        g.setColour(juce::Colour(0xffd7b414));`n        g.fillRoundedRectangle(stick, 3.0f);`n        juce::Path tri;`n        tri.addTriangle(stick.getCentreX(), stick.getY() + 6.0f,`n                        stick.getX() + 8.0f, stick.getBottom() - 7.0f,`n                        stick.getRight() - 8.0f, stick.getBottom() - 7.0f);`n        g.setColour(juce::Colour(0xff141414));`n        g.fillPath(tri);`n        g.setColour(juce::Colour(0xffd7b414));`n        g.setFont(juce::FontOptions(""Consolas"", 10.0f, juce::Font::bold));`n        g.drawText(""!"", stick, juce::Justification::centred);`n    }`n    {`n        juce::Rectangle<float> pipe(0.0f, baseH - 12.0f, baseW, 7.0f);`n        juce::ColourGradient pg(juce::Colour(0xff585e62), 0.0f, pipe.getY(),`n                                juce::Colour(0xff1e2226), 0.0f, pipe.getBottom(), false);`n        g.setGradientFill(pg);`n        g.fillRect(pipe);`n        for (float cx = 40.0f; cx < baseW; cx += 260.0f)`n        {`n            g.setColour(juce::Colour(0xff787e82));`n            g.fillRect(cx, pipe.getY() - 3.0f, 12.0f, pipe.getHeight() + 6.0f);`n            g.setColour(juce::Colour(0xff0a0c0d));`n            g.drawRect(cx, pipe.getY() - 3.0f, 12.0f, pipe.getHeight() + 6.0f, 1.0f);`n        }`n    }"

    $replacement = $anchor +
